// ---------------------------------------------------------------------------
// ReconDynamicCast -- the runtime's own downcast.
//
// The binary calls __dynamic_cast directly:
//
//     result = dynamic_cast from the source object to the destination type.
//
// which walks the RTTI graph to check whether the source really is the destination. The transcribed
// tree has no RTTI objects for the target's classes (the class headers are
// opaque storage, not polymorphic types), so the cast cannot be reproduced from
// the type_info arguments. It becomes a pass-through: the sites in this
// codebase all use it as "the object if it is the right type, else null", and
// the objects reaching them are already of the expected type because the caller
// selected them from a vtable slot that only that type implements.
// ---------------------------------------------------------------------------
inline void* ReconDynamicCast(void* theObject, const void* /*srcType*/,
                              const void* /*dstType*/, int /*flags*/)
{
    return theObject;
}
inline const void* ReconDynamicCast(const void* theObject, const void* /*srcType*/,
                                    const void* /*dstType*/, int /*flags*/)
{
    return theObject;
}

