// SCoinItem -- the element type of the `std::vector<SCoinItem>` in
// DrRpcEngine::call_QueryCoinList (`_ZNSt6vectorI9SCoinItemSaIS0_EE13_M_insert_auxE...`
// @0x1f1658). The vector's step is 8 bytes, so the record is two words.
// DrRpcEngine::call_QueryAllItems walks the response's "list" array and fills one
// of these per entry: the "value" node into the first word and the "getcoin" node
// into the second (DrRpcEngine.cpp, the `JSONNode_at(..., "value")` pair).
struct SCoinItem
{
    int mValue;     // +0x00  the "value" node
    int mGetCoin;   // +0x04  the "getcoin" node
};

// PLANTSETTING / TombConfig -- the element types of two more vectors the tree
// was missing:
//   _ZNSt6vectorIN4Sexy12PLANTSETTINGESaIS1_EE13_M_insert_auxE... @0x2be958
//   _ZNSt6vectorIN4Sexy10TombConfigESaIS0_EE13_M_insert_auxE...   @0x2beac4
// Both live in namespace Sexy and are only used as vector elements, so a size
// is all that is needed.
// TODO(recon): pin each record's extent from its vector's stride and name the
