using Sexy::PLANTSETTING;
using Sexy::TombConfig;

// ---------------------------------------------------------------------------
// The particle-engine value types. All three are vector elements in
// PIEffect.cpp, so the complete type is needed, and none had a declaration.
// The extents come from the vectors' strides:
//   PIParticleDefInstance  16 bytes  -- SaveParticleDefInstance writes four
//                                       fields and the stride is 16
//   PIValuePoint            8 bytes  -- the stride is `>> 3`
//   PIInterpolatorPoint     8 bytes  -- two words
// TODO(recon): name the fields once a body reads one by name.
// ---------------------------------------------------------------------------
namespace Sexy {
struct PIParticleDefInstance { float mField0; float mField1; int mField2; int mField3; };
struct PIValuePoint         { int mField0; int mField1; };
// Keyframe of a colour ramp. mField0 is the colour word InterpColor blends.
// mField1 is the key time.
struct PIInterpolatorPoint
{
    int   mField0 = 0;
    float mField1 = 0.0f;
};

// ObjectPool<T> -- the free-list allocator behind PIEffect's particle storage.
// Alloc takes the pool as its first argument. The four header words are the
// pool bookkeeping; the current Alloc does not walk a free list.
template <class T>
class ObjectPool
{
public:
    int mField0 = 0;
    int mField1 = 0;
    int mField2 = 0;
    int mField3 = 0;

    // Alloc(obj) -- hand back a slot. The pool is not wired to a real free list
    // here; the particle backend allocates straight from the heap instead.
    // TODO(recon): reproduce the free list once PIEffect's storage is ported.
    //
    // `new T` and not `operator new(sizeof(T))`: T is a plain aggregate with no
    // constructor, so a new-expression performs no initialisation and produces
    // exactly the raw slot the binary's pool hands back.
    static T* Alloc(ObjectPool<T>* thePool)
    {
        (void)thePool;
        return new T;
    }
};
} // namespace Sexy

// Glyph bounds and pen advance measured by Font::StringExtents.
struct TextExtents
{
    float mMinX = 0.0f;
    float mMinY = 0.0f;
    float mSpanX = 0.0f;
    float mSpanY = 0.0f;
    float mWidth = 0.0f;
    float mHeight = 0.0f;
};

// TodWeightedArray -- the { item, weight } pair the Tod picking helpers walk.
// The transcription classified the demangled type as an enum and emitted a
// one-int surrogate; the array it stands for is 8 bytes per element, because
// TodPickFromWeightedArray/TodPickArrayItemFromWeightedArray stride by two
// words and SeedChooserScreen's own copy of the picker reads `[1]` as the
// weight. It is spelled `mItem`/`mWeight` here to match
// PvZ\TodLib\Common\TodCommon.h and PvZ-src, and the layout is unchanged for
// the one-int call sites because an int converts to both fields.
struct TodWeightedArray
{
    int mItem;
    int mWeight;

    TodWeightedArray() : mItem(0), mWeight(0) {}
    TodWeightedArray(int theValue) : mItem(theValue), mWeight(0) {}
    operator int() const { return mItem; }
    TodWeightedArray& operator=(int theValue) { mItem = theValue; return *this; }
};

// TodWeightedGridArray -- NOT an enum. The transcriber emitted a one-int
// surrogate from the mangled name, but the binary's own consumer,
// TodPickFromWeightedGridArray @0x1FC4C0, walks the array with a stride of 12 and
// reads each element's weight from +8, so an element is three ints. That is also
// the layout the reference header PvZ\TodLib\Common\TodCommon.h:47 gives.
// Game/CutScene.cpp is the only user in this tree.
struct TodWeightedGridArray
{
    int mX;
    int mY;
    int mWeight;
};

// TodSmoothArray -- four words, stride 16. TodUpdateSmoothArrayPick @0x1FC5DC
// ages the two pick counters when the weight at +4 is positive, then zeros the
// chosen row's last-picked word and copies the old value into the second slot.
struct TodSmoothArray
{
    int mItem;
    float mWeight;
    float mLastPicked;
    float mSecondLastPicked;
};

