// Types the demangled signatures name that have no header of their own:
// the bodies only ever pass these by pointer, which an incomplete type
// is enough for. The ones with real storage are defined in the tree.
// TMLongCard -- the input layer's packed key card.
//
// The bodies use it as a VALUE and pass it on, so it
// needs a complete definition. It is one register word: the dump's declarations
// are all `TMLongCard` next to `int` locals of the same width, and it is
// assigned from and compared against ints.
struct TMLongCard
{
    int mValue;

    TMLongCard() : mValue(0) {}
    TMLongCard(int theValue) : mValue(theValue) {}
    template <class Word>
    TMLongCard(const Word& theValue) : mValue((int)(unsigned int)theValue) {}
    operator int() const { return mValue; }
    TMLongCard& operator=(int theValue) { mValue = theValue; return *this; }
};

