// TrailFlags -- the flag set of TrailDefinition::mTrailFlags. Taken from the PC
// reference source TodLib\Trail.h. Only referenced through a plain int so far.
enum TrailFlags {
    TRAIL_FLAG_LOOPS = 0,
};

// FloatParameterTrackNode / FloatParameterTrack -- one animated parameter track of
// a TodLib definition. Taken from the PC reference source TodLib\Definition.h.
// FloatTrackEvaluate walks nodes of 20 bytes: time, low, high, the curve used
// to blend this node into the next, and the distribution used to sample the
// node's own low/high pair. A track is that pointer plus a count.
// TrailDefinition (5 tracks at +0x10) occupies 0x38 bytes -- Board.cpp:22343 allocates
// exactly that much for it and its constructor clears the same 0x38 bytes, i.e.
// 0x10 + 5 * 8 == 0x38.
struct FloatParameterTrackNode
{
    float     mTime;
    float     mLowValue;
    float     mHighValue;
    TodCurves mCurveType;
    TodCurves mDistribution;
};
struct FloatParameterTrack
{
    FloatParameterTrackNode* mNodes;      // +0
    int                      mCountNodes; // +4
};

