// SortedKern -- one kerning pair, the element of FontData's kerning table.
//
// Three words: the first character, the second and the amount. The binary's
// own comparator is used as a qsort callback, so it is a plain function.
struct SortedKern
{
    int mChar;
    int mSecond;
    int mAmount;

    static int Compare(const void* a, const void* b);
};

