// UpdateAll / UpdateFAll / DrawAll vtable slot takes a `ModalFlags *`. Both are
// reproduced verbatim from the authoritative header
// PvZ\SexyAppFramework\Misc\Flags.h, where they also live in `namespace Sexy`.
// ---------------------------------------------------------------------------
namespace Sexy {

class FlagsMod
{
public:
    int mAddFlags;
    int mRemoveFlags;

    FlagsMod()
    {
        mAddFlags = 0;
        mRemoveFlags = 0;
    }
};

class ModalFlags
{
public:
    int mOverFlags;
    int mUnderFlags;
    bool mIsOver;

    int GetFlags() { return mIsOver ? mOverFlags : mUnderFlags; }
};

} // namespace Sexy

